        bool _bCase, ::cppu::OWeakObject& _rParent, ::osl::Mutex& _rMutex )
    {
        std::vector< OUString > aNames; aNames.reserve( _rColumns->size() );

        OUString sColumName;
        for (auto const& column : *_rColumns)
        {
            Reference< XPropertySet > xColumn(column, UNO_SET_THROW);
